//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub type PlayerId = u32;

#[derive(Default)]
struct BoardState {
    players: HashMap<PlayerId, i64>,
    total: i64,
}

/// Clones share the same scores, so each match thread keeps its own handle.
#[derive(Clone, Default)]
pub struct Board {
    state: Arc<Mutex<BoardState>>,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn join(&self, id: PlayerId, score: i64) {
        let mut state = self.state.lock().unwrap();
        let previous = state.players.insert(id, score).unwrap_or(0);
        state.total += score - previous;
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        let mut state = self.state.lock().unwrap();
        *state.players.get_mut(&id).unwrap() += points;
        state.total += points;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        let mut state = self.state.lock().unwrap();
        assert!(state.players.contains_key(&from), "unknown player {from}");
        assert!(state.players.contains_key(&to), "unknown player {to}");
        if from == to {
            return;
        }
        *state.players.get_mut(&from).unwrap() -= points;
        *state.players.get_mut(&to).unwrap() += points;
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        self.state.lock().unwrap().players[&id]
    }

    pub fn total(&self) -> i64 {
        self.state.lock().unwrap().total
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::thread;

    #[test]
    fn self_transfer_does_not_deadlock_and_preserves_score() {
        let board = Board::new();
        board.join(1, 50);
        board.transfer(1, 1, 20);
        assert_eq!(board.score(1), 50);
        assert_eq!(board.total(), 50);
    }

    #[test]
    fn concurrent_awards_do_not_lose_points() {
        let board = Board::new();
        board.join(1, 0);
        board.join(2, 0);

        let mut handles = Vec::new();
        for _ in 0..8 {
            let b = board.clone();
            handles.push(thread::spawn(move || {
                for _ in 0..1_000 {
                    b.award(1, 3);
                    b.award(2, 2);
                }
            }));
        }
        for h in handles {
            h.join().unwrap();
        }

        assert_eq!(board.score(1), 24_000);
        assert_eq!(board.score(2), 16_000);
        assert_eq!(board.total(), 40_000);
    }

    #[test]
    fn concurrent_bidirectional_transfers_do_not_deadlock_or_lose_points() {
        let board = Board::new();
        board.join(1, 10_000);
        board.join(2, 10_000);
        board.join(3, 10_000);

        let mut handles = Vec::new();
        for t in 0..6 {
            let b = board.clone();
            handles.push(thread::spawn(move || {
                for i in 0..1_000 {
                    match (t + i) % 4 {
                        0 => b.transfer(1, 2, 1),
                        1 => b.transfer(2, 1, 1),
                        2 => b.transfer(2, 3, 2),
                        _ => b.transfer(3, 1, 1),
                    }
                    b.transfer(1, 1, 5);
                }
            }));
        }
        for h in handles {
            h.join().unwrap();
        }

        assert_eq!(
            board.score(1) + board.score(2) + board.score(3),
            board.total()
        );
        assert_eq!(board.total(), 30_000);
    }

    #[test]
    fn rejoin_replaces_score_and_adjusts_total() {
        let board = Board::new();
        board.join(1, 10);
        board.join(1, 25);
        assert_eq!(board.score(1), 25);
        assert_eq!(board.total(), 25);
    }
}
